def weapons(me, enemy, arena):
    if enemy.x > me.x and abs(enemy.y - me.y) < 0.5 and me.weapons["front"]["state"] == "open":
        # Grab the enemy if it's in front and the clamp is open
        return grab("front")
    elif me.weapons["front"]["state"] == "holding":
        # Hold the enemy if already grabbed
        return None
    else:
        # Release the clamp if not holding
        return release("front")
